import type { RollingTrendPoint } from '../types';

export function buildRollingPath(
  rollingPoints: RollingTrendPoint[],
  key: 'pct_early_gt2' | 'ghost_rate_pct',
  w = 600,
  h = 56,
  pad = 4
): string {
  const vals = rollingPoints
    .map((p) => p[key])
    .filter((v): v is number => v != null);
  if (vals.length < 2) {
    // Return a simple horizontal line in the middle when insufficient data
    return `M0,${h / 2}L${w},${h / 2}`;
  }
  const min = Math.min(...vals);
  const max = Math.max(...vals);
  const span = max - min || 1;
  const pts = rollingPoints
    .map((p, i) => {
      const v = p[key];
      if (v == null) return null;
      const x = (i / (rollingPoints.length - 1)) * w;
      const y = h - pad - ((v - min) / span) * (h - 2 * pad);
      return `${x.toFixed(1)},${y.toFixed(1)}`;
    })
    .filter((s): s is string => s != null);
  return `M${pts.join('L')}`;
}